24	namespace MonoDreams.Demo.Camera;
25	
26	/// Camera block demo. Move a red circle inside a boundary rectangle with WASD/arrows;
27	/// switch between five fixed camera targets (numbered 1–5, each shown as a hoverable
28	/// region in the world) and a follow mode (key 0). The "smooth lerp" toggle controls
29	/// the damping on <see cref="CameraFollowTargetComponent"/>: when on, the camera eases
30	/// toward its target (ball in follow mode, or the corresponding zone center in fixed
31	/// modes); when off, it snaps instantly.
32	///
33	/// In follow mode the camera also zooms out a little as its center lags behind the
34	/// red dot — see <see cref="CameraLagZoomSystem"/>. The more the dot outruns the
35	/// camera (fast moves, or pushing into the camera-bounds edges), the wider the view.
36	///
37	/// Also in follow mode, when the red dot's center enters one of the four corner
38	/// zones the camera stops tracking the dot and instead prioritizes a fixed point a
39	/// little past that corner (a light-blue crosshair marks it) — see
40	/// <see cref="CornerPrioritySystem"/>. Leaving the corner zone hands tracking back
41	/// to the dot. This is the documented swap pattern: a second follow target whose
42	/// <see cref="CameraFollowTargetComponent.IsActive"/> flag we toggle against the ball's.
43	public class CameraDemoScreen : IGameScreen
44	{
45	    private const float BoundaryHalfWidth = 380f;
46	    private const float BoundaryHalfHeight = 220f;
47	    // Camera-movement bounds in follow mode — a little smaller than the boundary,
48	    // so the red dot can push past the camera's reach toward the screen edges.
49	    private const float CameraBoundsHalfWidth = 280f;
50	    private const float CameraBoundsHalfHeight = 140f;
51	    private const float ZoneSize = 80f;
52	    private const float BallRadius = 20f;
53	    private const float MoveSpeed = 240f;
54	    // How far past the boundary corner the camera overshoots when the red dot
55	    // enters a corner zone — pushed well past the boundary on both axes.
56	    private const float CornerOverscan = 150f;
57	
58	    private const float DampingSmooth = 5f;
59	    private const float DampingInstant = 100f;
60	
61	    // Minimap: a second camera fixed at the region center, rendered to a small box
62	    // anchored to the bottom-right of the HUD. The box keeps the 16:9 virtual aspect
63	    // so the downscaled world view isn't distorted.
64	    private const int MinimapWidth = 320;
65	    private const int MinimapHeight = 180;
66	    private const int MinimapMargin = 24;
67	    // Fraction of the tightest fit, leaving a margin around the region in the minimap.
68	    private const float MinimapFitPadding = 0.85f;
69	
70	    /// Keyboard-key 0..5 maps directly to enum index: 0 Follow, 1 TL, 2 TR,
71	    /// 3 BR, 4 BL, 5 Center. Reordering is intentional — clockwise around the
72	    /// boundary corners with Center last.
73	    public enum Mode { Follow, FixedTL, FixedTR, FixedBR, FixedBL, FixedCenter }
74	
75	    private readonly ContentManager _content;
76	    private readonly GraphicsDevice _graphicsDevice;
77	    private readonly MonoDreams.Component.Camera _camera;
78	    private readonly ViewportManager _viewportManager;
79	    private readonly SpriteBatch _spriteBatch;
80	    private readonly World _world;
81	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
82	    private readonly BitmapFont _font;
83	    // Second camera + its own target for the minimap (see MinimapWidth/Height).
84	    private readonly MonoDreams.Component.Camera _minimapCamera;
85	    private readonly RenderTarget2D _minimapTarget;
86	
87	    private ScreenController? _screenController;
88	    private Entity _ball;
89	    private Entity _cameraAnchor;
90	    private Entity _lerpToggle;
91	    private Entity _targetCross;
92	    private Entity _cameraBoundsRect;
93	    // Free-following anchor the camera prioritizes while the red dot sits in a
94	    // corner zone; carries the light-blue corner crosshair as a child.
95	    private Entity _cornerAnchor;
96	    private Entity _cornerCross;
97	    // While corner priority is engaged, the distance from the prioritized point to
98	    // the corner zone's center; null when disengaged. Drives the corner zoom-out.
99	    private float? _cornerZoomDistance;
100	    private Mode _mode = Mode.Follow;
101	    private bool _lerpSmooth = true;
102	
103	    private readonly Dictionary<Mode, Entity> _sidebarButtons = new();
104	    private readonly Dictionary<Mode, Entity> _worldZoneButtons = new();
105	
106	    public ISystem<GameState> UpdateSystem { get; }
107	    public ISystem<GameState> DrawSystem { get; }
108	    public World World => _world;
