110	    public CameraDemoScreen(GraphicsDevice graphicsDevice, ContentManager content, MonoDreams.Component.Camera camera,
111	        ViewportManager viewportManager, SpriteBatch spriteBatch)
112	    {
113	        _graphicsDevice = graphicsDevice;
114	        _content = content;
115	        _camera = camera;
116	        _viewportManager = viewportManager;
117	        _spriteBatch = spriteBatch;
118	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
119	        {
120	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
121	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
122	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
123	        };
124	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
125	
126	        camera.Position = Vector2.Zero;
127	
128	        // Minimap camera: same virtual resolution as the main camera (the mesh
129	        // projection is shared across render passes), fixed at the region center, and
130	        // zoomed so the whole boundary region fits with a margin. Never moved or zoomed.
131	        var fitZoom = Math.Min(
132	            viewportManager.VirtualWidth / (BoundaryHalfWidth * 2f),
133	            viewportManager.VirtualHeight / (BoundaryHalfHeight * 2f)) * MinimapFitPadding;
134	        _minimapCamera = new MonoDreams.Component.Camera(viewportManager.VirtualWidth, viewportManager.VirtualHeight)
135	        {
136	            Position = Vector2.Zero,
137	            Zoom = fitZoom,
138	        };
139	        _minimapTarget = new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight);
140	
141	        _world = new World();
142	        UpdateSystem = CreateUpdateSystem();
143	        DrawSystem = CreateDrawSystem();
144	    }
