147	    {
148	        _screenController = screenController;
149	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
150	
151	        var cursorTextures = new Dictionary<CursorType, Texture2D>
152	        {
153	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
