155	            [CursorType.Hand] = content.Load<Texture2D>("Cursor/hand"),
156	        };
157	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
158	
159	        _cameraAnchor = _world.CreateEntity();
160	        _cameraAnchor.Set(new TransformComponent(Vector2.Zero));
161	
162	        CreateBoundary();
163	        CreateCameraBoundsRect();
164	        CreateWorldZones();
165	        CreateBall();
166	        CreateTargetCross();
167	        CreateCornerPriorityAnchor();
168	        CreateCameraCenterCross();
