175	    // ─── public bridges for the keyboard system ───────────────────────────────
176	
177	    public void SetMode(Mode mode)
178	    {
179	        _mode = mode;
180	        foreach (var (m, btn) in _sidebarButtons) UpdateActive(btn, m == mode);
181	        foreach (var (m, btn) in _worldZoneButtons) UpdateActive(btn, m == mode);
182	
183	        // The dashed camera-bounds guide only makes sense while the camera tracks
184	        // the red dot — show it in follow mode, hide it in the fixed modes.
185	        SetCameraBoundsVisible(mode == Mode.Follow);
186	
187	        if (mode == Mode.Follow)
188	        {
189	            if (_cameraAnchor.Has<CameraFollowTargetComponent>())
190	                _cameraAnchor.Remove<CameraFollowTargetComponent>();
191	            if (!_ball.Has<CameraFollowTargetComponent>())
192	                _ball.Set(new CameraFollowTargetComponent());
193	            ApplyDampingTo(_ball);
194	            _ball.Get<CameraFollowTargetComponent>().Bounds = CameraBounds();
195	            ReparentTargetCross(_ball);
196	        }
197	        else
198	        {
199	            // Leaving follow mode hands the camera to the fixed anchor — make sure
200	            // any corner-priority override is cleared so it can't fight the anchor.
201	            DisengageCornerPriority();
202	            if (_ball.Has<CameraFollowTargetComponent>())
203	                _ball.Remove<CameraFollowTargetComponent>();
204	            var anchorTransform = _cameraAnchor.Get<TransformComponent>();
205	            anchorTransform.Position = ModeCameraTarget(mode);
206	            if (!_cameraAnchor.Has<CameraFollowTargetComponent>())
207	                _cameraAnchor.Set(new CameraFollowTargetComponent());
208	            ApplyDampingTo(_cameraAnchor);
209	            ReparentTargetCross(_cameraAnchor);
210	
211	            if (!_lerpSmooth) _camera.Position = anchorTransform.Position;
212	        }
213	    }
214	
215	    private void ReparentTargetCross(Entity newParent)
216	    {
217	        if (!_targetCross.IsAlive) return;
218	        // SetParent overwrites ChildOfComponent + transform.Parent in place;
219	        // we deliberately skip RemoveParent so the cross's LOCAL position stays
220	        // at (0,0). RemoveParent snapshots the current world position into the
221	        // local one, which would double the offset on the next reparent.
222	        _targetCross.SetParent(newParent);
223	        _targetCross.Get<TransformComponent>().Position = Vector2.Zero;
224	    }
225	
226	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
227	
228	    public void ToggleLerp()
229	    {
230	        if (!_lerpToggle.IsAlive || !_lerpToggle.Has<ToggleSwitchComponent>()) return;
231	        var sw = _lerpToggle.Get<ToggleSwitchComponent>();
232	        sw.On = !sw.On;
233	        _lerpSmooth = sw.On;
234	        _lerpToggle.Set(sw);
235	
236	        if (_ball.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_ball);
237	        if (_cornerAnchor.IsAlive && _cornerAnchor.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_cornerAnchor);
238	        if (_cameraAnchor.Has<CameraFollowTargetComponent>())
239	        {
240	            ApplyDampingTo(_cameraAnchor);
241	            if (!_lerpSmooth) _camera.Position = _cameraAnchor.Get<TransformComponent>().Position;
242	        }
243	    }
244	
245	    private void ApplyDampingTo(Entity target)
246	    {
247	        if (!target.Has<CameraFollowTargetComponent>()) return;
248	        var ft = target.Get<CameraFollowTargetComponent>();
249	        ft.DampingX = _lerpSmooth ? DampingSmooth : DampingInstant;
250	        ft.DampingY = _lerpSmooth ? DampingSmooth : DampingInstant;
251	        ft.MaxDistanceX = 10000f;
252	        ft.MaxDistanceY = 10000f;
253	    }
254	
255	    /// Per-frame corner-priority tick, driven by <see cref="CornerPrioritySystem"/>.
256	    /// Only engages in follow mode: when the red dot's center is inside a corner zone,
257	    /// the camera prioritizes the corner's overscan point (light-blue cross) by toggling
258	    /// the corner anchor active and the ball inactive; otherwise the ball stays the
259	    /// target. Runs after the ball moves and after mode switches, before the follow
260	    /// system, so at most one target is active when <see cref="CameraFollowSystem"/> reads.
261	    public void UpdateCornerPriority()
262	    {
263	        if (_mode != Mode.Follow)
264	        {
265	            DisengageCornerPriority();
266	            return;
267	        }
268	
269	        var ballCenter = _ball.Get<TransformComponent>().Position;
270	        if (TryGetCornerZone(ballCenter, out var corner))
271	        {
272	            var point = CornerPriorityPoint(corner);
273	            _cornerAnchor.Get<TransformComponent>().Position = point;
274	            _cornerAnchor.Get<CameraFollowTargetComponent>().IsActive = true;
275	            if (_ball.Has<CameraFollowTargetComponent>())
276	                _ball.Get<CameraFollowTargetComponent>().IsActive = false;
277	            SetCornerCrossVisible(true);
278	            // How far the prioritized point sits beyond the corner zone's center —
279	            // CameraLagZoomSystem reads this to zoom out proportionally.
280	            _cornerZoomDistance = (point - CornerZoneCenter(corner)).Length();
281	        }
282	        else
283	        {
284	            DisengageCornerPriority();
285	        }
286	    }
287	
288	    /// Distance the prioritized corner point sits from the corner zone's center while
289	    /// corner priority is engaged; null otherwise. Read by <see cref="CameraLagZoomSystem"/>.
290	    public float? CornerZoomDistance => _cornerZoomDistance;
291	
292	    /// Hands camera tracking back to the red dot and hides the corner crosshair.
293	    /// Safe to call in any mode — guards on component presence.
294	    private void DisengageCornerPriority()
295	    {
296	        if (_cornerAnchor.IsAlive && _cornerAnchor.Has<CameraFollowTargetComponent>())
297	            _cornerAnchor.Get<CameraFollowTargetComponent>().IsActive = false;
298	        if (_ball.IsAlive && _ball.Has<CameraFollowTargetComponent>())
299	            _ball.Get<CameraFollowTargetComponent>().IsActive = true;
300	        SetCornerCrossVisible(false);
301	        _cornerZoomDistance = null;
302	    }
303	
304	    private void SetCornerCrossVisible(bool visible)
305	    {
306	        if (!_cornerCross.IsAlive) return;
307	        if (visible && !_cornerCross.Has<VisibleComponent>())
308	            _cornerCross.Set<VisibleComponent>();
309	        else if (!visible && _cornerCross.Has<VisibleComponent>())
310	            _cornerCross.Remove<VisibleComponent>();
311	    }
312	
313	    // The four corner zones the dot can trigger priority from. Center (5) is excluded.
314	    private static readonly Mode[] CornerModes =
315	        { Mode.FixedTL, Mode.FixedTR, Mode.FixedBR, Mode.FixedBL };
316	
317	    /// True when <paramref name="ballCenter"/> lies inside one of the four corner zones,
318	    /// yielding which corner it is.
319	    private static bool TryGetCornerZone(Vector2 ballCenter, out Mode corner)
320	    {
321	        foreach (var mode in CornerModes)
322	        {
323	            var topLeft = ZoneTopLeft(mode);
324	            var zone = new Rectangle((int)topLeft.X, (int)topLeft.Y, (int)ZoneSize, (int)ZoneSize);
325	            if (zone.Contains((int)ballCenter.X, (int)ballCenter.Y))
326	            {
327	                corner = mode;
328	                return true;
329	            }
330	        }
331	        corner = Mode.Follow;
332	        return false;
333	    }
334	
335	    /// World-space center of a corner zone square.
336	    private static Vector2 CornerZoneCenter(Mode m) =>
337	        ZoneTopLeft(m) + new Vector2(ZoneSize / 2f, ZoneSize / 2f);
338	
339	    /// The fixed point the camera looks at while the dot is in a corner zone: the
340	    /// boundary corner pushed out by <see cref="CornerOverscan"/> on both axes.
341	    private static Vector2 CornerPriorityPoint(Mode m) => m switch
342	    {
343	        Mode.FixedTL => new Vector2(-BoundaryHalfWidth - CornerOverscan, -BoundaryHalfHeight - CornerOverscan),
344	        Mode.FixedTR => new Vector2( BoundaryHalfWidth + CornerOverscan, -BoundaryHalfHeight - CornerOverscan),
345	        Mode.FixedBR => new Vector2( BoundaryHalfWidth + CornerOverscan,  BoundaryHalfHeight + CornerOverscan),
346	        Mode.FixedBL => new Vector2(-BoundaryHalfWidth - CornerOverscan,  BoundaryHalfHeight + CornerOverscan),
347	        _ => Vector2.Zero,
348	    };
349	
350	    private static void UpdateActive(Entity entity, bool active)
351	    {
352	        if (!entity.IsAlive || !entity.Has<DemoButtonComponent>()) return;
353	        ref var b = ref entity.Get<DemoButtonComponent>();
354	        b.IsActive = active;
355	    }
356	
357	    // Camera centers exactly on the zone the user clicked. Zone centers sit at the
358	    // corners offset by half the zone size so the zone sprite is fully on-screen.
359	    private static Vector2 ModeCameraTarget(Mode m)
360	    {
361	        var halfZone = ZoneSize / 2f;
362	        return m switch
363	        {
364	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth + halfZone, -BoundaryHalfHeight + halfZone),
365	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - halfZone, -BoundaryHalfHeight + halfZone),
366	            Mode.FixedCenter => Vector2.Zero,
367	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth + halfZone,  BoundaryHalfHeight - halfZone),
368	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - halfZone,  BoundaryHalfHeight - halfZone),
369	            _                => Vector2.Zero,
370	        };
371	    }
372	
373	    private static Vector2 ZoneTopLeft(Mode m)
374	    {
375	        var half = ZoneSize / 2f;
376	        return m switch
377	        {
378	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth,             -BoundaryHalfHeight),
379	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - ZoneSize,  -BoundaryHalfHeight),
380	            Mode.FixedCenter => new Vector2(-half, -half),
381	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth,              BoundaryHalfHeight - ZoneSize),
382	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - ZoneSize,   BoundaryHalfHeight - ZoneSize),
383	            _ => Vector2.Zero,
384	        };
385	    }
