389	    private void OnButtonClicked(in DemoButtonClicked msg)
390	    {
391	        switch (msg.Id)
392	        {
393	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
394	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
395	            case "mode.follow": SetMode(Mode.Follow); break;
396	            case "mode.tl":     SetMode(Mode.FixedTL); break;
397	            case "mode.tr":     SetMode(Mode.FixedTR); break;
398	            case "mode.center": SetMode(Mode.FixedCenter); break;
399	            case "mode.bl":     SetMode(Mode.FixedBL); break;
400	            case "mode.br":     SetMode(Mode.FixedBR); break;
401	            case "toggle.lerp": ToggleLerp(); break;
402	        }
403	    }
