407	    private void CreateBoundary()
408	    {
409	        var bounds = new Rectangle(
410	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
411	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
412	
413	        var boundary = _world.CreateEntity();
414	        boundary.Set(new TransformComponent(Vector2.Zero));
415	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
416	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
417	        boundary.Set(draw);
418	        boundary.Set<VisibleComponent>();
419	    }
420	
421	    /// World-space rectangle the camera position is clamped to in follow mode.
422	    private static Rectangle CameraBounds() => new(
423	        -(int)CameraBoundsHalfWidth, -(int)CameraBoundsHalfHeight,
424	        (int)CameraBoundsHalfWidth * 2, (int)CameraBoundsHalfHeight * 2);
425	
426	    /// Soft-yellow dashed guide showing how far the camera can travel in follow
427	    /// mode. Created once; its visibility is toggled by <see cref="SetMode"/> so it
428	    /// only appears while the red dot is the camera target.
429	    private void CreateCameraBoundsRect()
430	    {
431	        _cameraBoundsRect = _world.CreateEntity();
432	        _cameraBoundsRect.Set(new TransformComponent(Vector2.Zero));
433	        // 0.25 sits just above the solid boundary outline (0.2) and below the
434	        // world-zone outlines, ball, and crosses.
435	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.25f };
436	        draw.SetMeshData(new DashedRectangleOutlineMeshGenerator(
437	            CameraBounds(), thickness: 2f, color: SproutPalette.SoftYellow, dashLength: 14f, gapLength: 9f));
438	        _cameraBoundsRect.Set(draw);
439	        // VisibleComponent is added/removed by SetCameraBoundsVisible — no
440	        // CullingSystem runs in this demo, so the tag fully controls visibility.
441	    }
442	
443	    private void SetCameraBoundsVisible(bool visible)
444	    {
445	        if (!_cameraBoundsRect.IsAlive) return;
446	        if (visible && !_cameraBoundsRect.Has<VisibleComponent>())
447	            _cameraBoundsRect.Set<VisibleComponent>();
448	        else if (!visible && _cameraBoundsRect.Has<VisibleComponent>())
449	            _cameraBoundsRect.Remove<VisibleComponent>();
450	    }
