452	    private void CreateWorldZones()
453	    {
454	        // Numbering matches the keyboard digits — 1 TL, 2 TR, 3 BR, 4 BL, 5 Center.
455	        CreateWorldZone(Mode.FixedTL,     "1", "mode.tl");
456	        CreateWorldZone(Mode.FixedTR,     "2", "mode.tr");
457	        CreateWorldZone(Mode.FixedBR,     "3", "mode.br");
458	        CreateWorldZone(Mode.FixedBL,     "4", "mode.bl");
459	        CreateWorldZone(Mode.FixedCenter, "5", "mode.center");
460	    }
