462	    private void CreateWorldZone(Mode mode, string label, string id)
463	    {
464	        var topLeft = ZoneTopLeft(mode);
465	        var sharedTransform = new TransformComponent(topLeft);
466	
467	        var container = _world.CreateEntity();
468	        container.Set(sharedTransform);
469	
470	        const float labelScale = 0.50f;
471	        var measured = _font.MeasureString(label);
472	        var labelSize = new Vector2(measured.Width * labelScale, measured.Height * labelScale);
473	        var labelOffset = new Vector2((ZoneSize - labelSize.X) / 2f, (ZoneSize - labelSize.Y) / 2f);
474	        var labelEntity = _world.CreateEntity();
475	        labelEntity.Set(new TransformComponent(labelOffset));
476	        labelEntity.SetParent(container);
477	        labelEntity.Set(new DynamicTextComponent
478	        {
479	            Target = RenderTargetID.Main,
480	            LayerDepth = 0.35f,
481	            TextContent = label,
482	            Font = _font,
483	            Color = SproutPalette.TextLight,
484	            Scale = labelScale,
485	            IsRevealed = true,
486	            VisibleCharacterCount = int.MaxValue,
487	        });
488	        labelEntity.Set<VisibleComponent>();
489	
490	        var outline = _world.CreateEntity();
491	        outline.Set(sharedTransform);
492	        outline.Set(new SimpleButtonComponent
493	        {
494	            Size = new Vector2(ZoneSize, ZoneSize),
495	            LineThickness = 1.5f,
496	            Color = SproutPalette.TextLight,
497	            TextEntity = labelEntity,
498	            Target = RenderTargetID.Main,
499	        });
500	        outline.Set(new DemoButtonComponent
501	        {
502	            Id = id,
503	            DefaultColor = SproutPalette.TextLight,
504	            HoveredColor = SproutPalette.TextHover,
505	            ActiveColor = SproutPalette.TextSelected,
506	        });
507	        outline.Set<VisibleComponent>();
508	        _worldZoneButtons[mode] = outline;
509	    }
