511	    private void CreateBall()
512	    {
513	        _ball = _world.CreateEntity();
514	        _ball.Set(new TransformComponent(Vector2.Zero));
515	        _ball.Set(new PlayerBallTag());
516	        // 0.97 puts the ball above the world-zone button outlines (those get
517	        // LayerDepth=0.95 from ButtonMeshPrepSystem) so the ball doesn't get
518	        // clipped by a zone's outline as it crosses through.
519	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.97f };
520	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, BallRadius, SproutPalette.Crimson, segments: 32));
521	        _ball.Set(draw);
522	        _ball.Set<VisibleComponent>();
523	
524	        // Clickable hit-area for the ball — child entity offset to the ball's
525	        // top-left so the bounds-based hit test wraps the circle. Clicking the
526	        // ball switches to follow mode.
527	        var hitArea = _world.CreateEntity();
528	        hitArea.Set(new TransformComponent(new Vector2(-BallRadius, -BallRadius)));
529	        hitArea.SetParent(_ball);
530	        hitArea.Set(new SimpleButtonComponent
531	        {
532	            Size = new Vector2(BallRadius * 2, BallRadius * 2),
533	            LineThickness = 0f,
534	            Color = Color.Transparent,
535	            FillColor = Color.Transparent,
536	            TextEntity = null,
537	            Target = RenderTargetID.Main,
538	        });
539	        hitArea.Set(new DemoButtonComponent
540	        {
541	            Id = "mode.follow",
542	            DefaultColor = Color.Transparent,
543	            HoveredColor = Color.Transparent,
544	            ActiveColor = Color.Transparent,
545	        });
546	        hitArea.Set<VisibleComponent>();
547	    }
548	
549	    /// Green cross marking where the camera *wants* to be. Parented to whichever
550	    /// entity currently has <see cref="CameraFollowTargetComponent"/> so it sits
551	    /// exactly at the target — when the camera lerps, the green cross stays put
552	    /// and the screen-center yellow cross drifts toward it.
553	    private void CreateTargetCross()
554	    {
555	        _targetCross = _world.CreateEntity();
556	        _targetCross.Set(new TransformComponent(Vector2.Zero));
557	        // 0.98 puts the cross above the ball (0.97) so the target marker is
558	        // never occluded when it sits on the ball in follow mode.
559	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.98f };
560	        draw.SetMeshData(CrossMesh(armPixels: 16, thicknessPixels: 3, color: Color.Black));
561	        _targetCross.Set(draw);
562	        _targetCross.Set<VisibleComponent>();
563	    }
564	
565	    /// Free-following anchor for the corner-priority behavior, plus its light-blue
566	    /// crosshair child. The anchor carries a <see cref="CameraFollowTargetComponent"/>
567	    /// with no <c>Bounds</c> (so the camera can overshoot past the boundary corner) and
568	    /// starts inactive — <see cref="CornerPrioritySystem"/> activates it against the ball
569	    /// while the dot sits in a corner zone. The crosshair is parented to the anchor and
570	    /// its visibility is toggled with the override, so it always sits on the target point.
571	    private void CreateCornerPriorityAnchor()
572	    {
573	        _cornerAnchor = _world.CreateEntity();
574	        _cornerAnchor.Set(new TransformComponent(Vector2.Zero));
575	        _cornerAnchor.Set(new CameraFollowTargetComponent { IsActive = false });
576	        ApplyDampingTo(_cornerAnchor);
577	
578	        _cornerCross = _world.CreateEntity();
579	        _cornerCross.Set(new TransformComponent(Vector2.Zero));
580	        _cornerCross.SetParent(_cornerAnchor);
581	        // 0.985 sits just above the green target cross (0.98) so the override marker
582	        // reads as the foremost crosshair while it's showing.
583	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.985f };
584	        draw.SetMeshData(CrossMesh(armPixels: 16, thicknessPixels: 3, color: SproutPalette.SkyBlue));
585	        _cornerCross.Set(draw);
586	        // VisibleComponent is added/removed by SetCornerCrossVisible — no CullingSystem
587	        // runs in this demo, so the tag fully controls visibility.
588	    }
589	
590	    /// Yellow cross drawn on HUD at the screen center — marks the point the
591	    /// camera is currently looking at. Camera-independent (HUD is not affected
592	    /// by the view transform), so this stays put even as the world scrolls.
593	    private void CreateCameraCenterCross()
594	    {
595	        var entity = _world.CreateEntity();
596	        entity.Set(new TransformComponent(new Vector2(
597	            _viewportManager.VirtualWidth / 2f,
598	            _viewportManager.VirtualHeight / 2f)));
599	        var draw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.92f };
600	        draw.SetMeshData(CrossMesh(armPixels: 14, thicknessPixels: 3, color: Color.White));
601	        entity.Set(draw);
602	        entity.Set<VisibleComponent>();
603	    }
604	
605	    /// Screen-space box (virtual coords) where the minimap is composited, anchored to
606	    /// the bottom-right of the HUD.
607	    private Rectangle MinimapDestination() => new(
608	        _viewportManager.VirtualWidth - MinimapMargin - MinimapWidth,
609	        _viewportManager.VirtualHeight - MinimapMargin - MinimapHeight,
610	        MinimapWidth, MinimapHeight);
611	
612	    /// HUD chrome for the minimap: an opaque backdrop (so the minimap's transparent
613	    /// areas don't reveal the world behind the HUD) and a frame ring just outside the
614	    /// composited image. The minimap image itself is drawn by MasterRenderSystem's
615	    /// minimap composite on top of this backdrop, inside the frame.
616	    private void CreateMinimapFrame()
617	    {
618	        var dest = MinimapDestination();
619	
620	        var bg = _world.CreateEntity();
621	        bg.Set(new TransformComponent(Vector2.Zero));
622	        // 0.90 keeps the backdrop below the screen-center cross (0.92) and cursor.
623	        var bgDraw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.90f };
624	        bgDraw.SetMeshData(new FilledRectangleMeshGenerator(dest, SproutPalette.DarkBgSecondary));
625	        bg.Set(bgDraw);
626	        bg.Set<VisibleComponent>();
627	
628	        var frameRect = new Rectangle(dest.X - 2, dest.Y - 2, dest.Width + 4, dest.Height + 4);
629	        var frame = _world.CreateEntity();
630	        frame.Set(new TransformComponent(Vector2.Zero));
631	        var frameDraw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.91f };
632	        frameDraw.SetMeshData(new RectangleOutlineMeshGenerator(frameRect, thickness: 3f, color: SproutPalette.TextLight));
633	        frame.Set(frameDraw);
634	        frame.Set<VisibleComponent>();
635	    }
636	
637	    private static CompositeMeshGenerator CrossMesh(int armPixels, int thicknessPixels, Color color)
638	    {
639	        var halfT = thicknessPixels / 2;
640	        return new CompositeMeshGenerator()
641	            .Add(new FilledRectangleMeshGenerator(
642	                new Rectangle(-armPixels, -halfT, armPixels * 2, thicknessPixels), color))
643	            .Add(new FilledRectangleMeshGenerator(
644	                new Rectangle(-halfT, -armPixels, thicknessPixels, armPixels * 2), color));
645	    }
646	
647	    // ─── HUD ────────────────────────────────────────────────────────────────
648	
649	    private void BuildHud(ContentManager content)
650	    {
651	        var squareButtons = content.Load<Texture2D>("SproutLands/Buttons/square_26x26");
652	        var settingsSheet = content.Load<Texture2D>("SproutLands/Buttons/settings_buttons");
653	
654	        DemoHeader.Build(
655	            _world, _viewportManager, _font, squareButtons,
656	            title: "camera",
657	            descriptionLines: new[]
658	            {
659	                "Use keyboard keys 0 to 5 to switch the camera target",
660	                "and the L key to toggle camera lerp.",
661	                "Use the WASD keys to control the red dot.",
662	            });
663	
664	        BuildSidebar(squareButtons, settingsSheet);
665	    }
666	
667	    private void BuildSidebar(Texture2D squareButtons, Texture2D settingsSheet)
668	    {
669	        var capStyle = new KeyCapStyle
670	        {
671	            SpriteSheet = squareButtons,
672	            DefaultSource = SproutSquareButtons.CreamLight,
673	            HoverSource   = SproutSquareButtons.CreamDark,
674	            ActiveSource  = SproutSquareButtons.TanDark,
675	            // 42 matches the lerp toggle pill width so all sidebar elements
676	            // line up on a shared left edge.
677	            CapPixels = 42,
678	            CapLabelScale = 0.22f,
679	            CapLabelColor = SproutPalette.WarmBrown,
680	        };
681	        var rowStyle = new KeyRowStyle
682	        {
683	            LabelColor = SproutPalette.TextLight,
684	            HoverColor = SproutPalette.TextHover,
685	            ActiveColor = SproutPalette.TextSelected,
686	            LabelScale = 0.18f,
687	            Gap = 10f,
688	            BackgroundColor = SproutPalette.DarkBgSecondary,
689	            HoverBackgroundColor = SproutPalette.DarkBgSecondary,
690	            ActiveBackgroundColor = SproutPalette.DarkBgSecondary,
691	            BackgroundPaddingX = 10f,
692	            BackgroundPaddingY = 6f,
693	        };
694	
695	        (Entity Container, Entity Outline, Vector2 Size) Row(string id, string key, string label) =>
696	            _world.CreateKeyRow(id, key, label, _font, capStyle, rowStyle, layerDepth: 0.96f);
697	
698	        // Order: 0 follow, 1 TL, 2 TR, 3 BR, 4 BL, 5 center.
699	        var follow = Row("mode.follow", "0", "follow red dot");
700	        var tl     = Row("mode.tl",     "1", "top-left");
701	        var tr     = Row("mode.tr",     "2", "top-right");
702	        var br     = Row("mode.br",     "3", "bottom-right");
703	        var bl     = Row("mode.bl",     "4", "bottom-left");
704	        var center = Row("mode.center", "5", "center");
705	
706	        // Toggle pill native is 28x18 (aspect ~1.56). Draw at 42x27 = native × 1.5
707	        // so the aspect ratio is preserved and the pill scales to match the cap chip.
708	        var lerp = _world.CreateToggleRow(
709	            id: "toggle.lerp",
710	            rowLabel: "smooth lerp",
711	            font: _font,
712	            toggleSheet: settingsSheet,
713	            offSource: SproutSettings.ToggleOff,
714	            onSource: SproutSettings.ToggleOn,
715	            initiallyOn: _lerpSmooth,
716	            toggleSize: new Vector2(42, 27),
717	            row: rowStyle,
718	            layerDepth: 0.96f);
719	
720	        _sidebarButtons[Mode.Follow]      = follow.Outline;
721	        _sidebarButtons[Mode.FixedTL]     = tl.Outline;
722	        _sidebarButtons[Mode.FixedTR]     = tr.Outline;
723	        _sidebarButtons[Mode.FixedBR]     = br.Outline;
724	        _sidebarButtons[Mode.FixedBL]     = bl.Outline;
725	        _sidebarButtons[Mode.FixedCenter] = center.Outline;
726	        _lerpToggle = lerp.Outline;
727	
728	        const float rowGap = 6f;       // gap BETWEEN per-row backgrounds
729	        const float groupGap = 16f;    // larger gap before the lerp toggle group
730	
731	        new AutoLayoutBuilder(_world, _viewportManager)
732	            .CreateRoot(ScreenAnchor.TopLeft, RenderTargetID.HUD)
733	            .Direction(LayoutDirection.Vertical)
734	            .Gap(rowGap)
735	            // Screen-root stacks roots vertically, so the sidebar already lands
736	            // below the header automatically — just add a small breathing pad.
737	            .Padding(20 /* top */, 12 /* right */, 12 /* bottom */, 12 /* left */)
738	            .AlignCross(CrossAxisAlignment.Start)
739	            .AddSlot(slot => slot.Attach(follow.Container).MeasureWith(_ => follow.Size))
740	            .AddSlot(slot => slot.Attach(tl.Container).MeasureWith(_ => tl.Size))
741	            .AddSlot(slot => slot.Attach(tr.Container).MeasureWith(_ => tr.Size))
742	            .AddSlot(slot => slot.Attach(br.Container).MeasureWith(_ => br.Size))
743	            .AddSlot(slot => slot.Attach(bl.Container).MeasureWith(_ => bl.Size))
744	            .AddSlot(slot => slot.Attach(center.Container).MeasureWith(_ => center.Size))
745	            .AddSlot(slot => slot.Attach(_world.CreateEntity()).MeasureWith(_ => new Vector2(0, groupGap - rowGap)))
746	            .AddSlot(slot => slot.Attach(lerp.Container).MeasureWith(_ => lerp.Size))
747	            .Build();
748	    }
749	
750	    // ─── pipeline ────────────────────────────────────────────────────────────
751	
752	    private SequentialSystem<GameState> CreateUpdateSystem()
753	    {
754	        return new SequentialSystem<GameState>(
755	            new CursorInputSystem(_world),
756	            new IntrinsicSizingSystem(_world),
757	            new AutoLayoutSystem(_world, _viewportManager),
758	            new DemoButtonInteractionSystem(_world),
759	            new DemoIconRecolorSystem(_world),
760	            new ToggleSwitchSystem(_world),
761	            new PlayerBallMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, BallRadius, MoveSpeed),
762	            new CameraDemoInputSystem(this),
763	            // Runs after the ball moved and after mode switches, before the follow
764	            // system, so the right target is active when the camera resolves.
765	            new CornerPrioritySystem(this),
766	            new CameraFollowSystem(_world, _camera),
767	            // Runs after the follow system so it reads this frame's resolved
768	            // camera position when measuring the lag behind the red dot.
769	            new CameraLagZoomSystem(_world, _camera, this),
770	            new HierarchySystem(_world),
771	            new CursorPositionSystem(_world, _camera, _viewportManager),
772	            new CursorDrawPrepSystem(_world));
773	    }
774	
775	    private SequentialSystem<GameState> CreateDrawSystem()
776	    {
777	        return new SequentialSystem<GameState>(
778	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
779	            new TextPrepSystem(_world, pixelPerfectRendering: false),
780	            new MeshPrepSystem(_world),
781	            new ButtonMeshPrepSystem(_world),
782	            // World view through the main camera, plus screen-space UI/HUD passes.
783	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
784	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
785	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
786	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
787	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
788	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
789	            // Minimap: the same world (Main) entities through a second camera fixed at the
790	            // region center, rendered into its own target — just another render pass.
791	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
792	                RenderTargetID.Main, _minimapTarget, _minimapCamera),
793	            // Composite the targets onto the screen; the minimap lands in its bottom-right box.
794	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
795	            {
796	                RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
797	                RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
798	                RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
799	                RenderLayer.Overlay(_minimapTarget, MinimapDestination(), SamplerState.LinearClamp),
800	            }));
801	    }
802	
803	    public void Dispose()
804	    {
805	        UpdateSystem.Dispose();
806	        DrawSystem.Dispose();
807	        foreach (var rt in _renderTargets.Values) rt.Dispose();
808	        _minimapTarget.Dispose();
809	        _world.Dispose();
810	        GC.SuppressFinalize(this);
811	    }
812	}
813	
814	/// Tag identifying the player-controlled circle in the camera demo.
815	public struct PlayerBallTag { }
816	
817	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
818	/// clamping its position so the ball stays inside the boundary rectangle.
819	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
820	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
821	{
822	    private readonly float _halfWidth;
823	    private readonly float _halfHeight;
824	    private readonly float _radius;
825	    private readonly float _speed;
826	
827	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
828	        : base(world)
829	    {
830	        _halfWidth = halfWidth;
831	        _halfHeight = halfHeight;
832	        _radius = radius;
833	        _speed = speed;
834	    }
835	
836	    protected override void Update(GameState state, in Entity entity)
837	    {
838	        var keyboard = Keyboard.GetState();
839	        var dir = Vector2.Zero;
840	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
841	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
842	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
843	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
844	        if (dir != Vector2.Zero) dir.Normalize();
845	
846	        var transform = entity.Get<TransformComponent>();
847	        var next = transform.Position + dir * _speed * state.Time;
848	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
849	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
850	        transform.Position = next;
851	    }
852	}
853	
854	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
855	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
856	/// fires once per release-then-press cycle.
857	public class CameraDemoInputSystem : ISystem<GameState>
858	{
859	    private readonly CameraDemoScreen _screen;
860	    private KeyboardState _previous;
861	    public bool IsEnabled { get; set; } = true;
862	
863	    public CameraDemoInputSystem(CameraDemoScreen screen)
864	    {
865	        _screen = screen;
866	        _previous = Keyboard.GetState();
867	    }
868	
869	    public void Update(GameState state)
870	    {
871	        if (!IsEnabled) return;
872	        var current = Keyboard.GetState();
873	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
874	
875	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
876	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
877	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
878	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
879	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
880	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
881	        if (Pressed(Keys.L)) _screen.ToggleLerp();
882	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
883	
884	        _previous = current;
885	    }
886	
887	    public void Dispose() => GC.SuppressFinalize(this);
888	}
889	
890	/// Drives the screen's corner-priority override each frame (see
891	/// <see cref="CameraDemoScreen.UpdateCornerPriority"/>). The screen owns the entities
892	/// and mode state, so the per-frame tick lives there; this system just forwards it at
893	/// the right pipeline slot — after movement/mode switches, before the follow system.
894	public class CornerPrioritySystem : ISystem<GameState>
895	{
896	    private readonly CameraDemoScreen _screen;
897	    public bool IsEnabled { get; set; } = true;
898	
899	    public CornerPrioritySystem(CameraDemoScreen screen) => _screen = screen;
900	
901	    public void Update(GameState state)
902	    {
903	        if (!IsEnabled) return;
904	        _screen.UpdateCornerPriority();
905	    }
906	
907	    public void Dispose() => GC.SuppressFinalize(this);
908	}
909	
910	/// Zooms the camera out a little, and eases the applied zoom toward that target so it
911	/// widens and recovers smoothly. Two sources drive the zoom-out:
912	///
913	/// 1. <b>Follow lag</b> — while the red dot is the active target, the world-space
914	///    distance between the ball and the resolved camera position. It grows when the
915	///    dot outruns the camera or pushes past the camera-bounds edges.
916	/// 2. <b>Corner priority</b> — while the camera prioritizes a corner point (the dot
917	///    sits in a corner zone), the distance from that point to the corner zone's center
918	///    (<see cref="CameraDemoScreen.CornerZoomDistance"/>). This is the dominant source
919	///    when engaged, so the view stays widened the whole time it looks past the corner.
920	///
921	/// Each distance maps linearly to a zoom reduction, capped at <see cref="MaxZoomOut"/>.
922	/// When neither applies (fixed modes, dot centered) the target zoom is 1. This only
923	/// writes <c>Camera.Zoom</c>, so it never competes with <see cref="CameraFollowSystem"/>'s
924	/// ownership of <c>Camera.Position</c>.
925	public class CameraLagZoomSystem : ISystem<GameState>
926	{
927	    // Follow-lag distance (in world units) at which the zoom-out reaches its full
928	    // MaxZoomOut. Sized for this demo's boundary/camera-bounds geometry.
929	    private const float MaxLag = 150f;
930	    // Corner-priority distance (blue point ↔ corner center) that maps to full MaxZoomOut.
931	    // Kept above the geometry's actual ~270px so the corner zoom stays proportional
932	    // (below the cap) and scales if the overscan changes.
933	    private const float CornerZoomReferenceDistance = 320f;
934	    // Largest zoom reduction; 0.18 means the camera widens to at most 0.82× — "a little".
935	    private const float MaxZoomOut = 0.18f;
936	    // Exponential easing rate for the applied zoom, matched to the smooth-lerp feel.
937	    private const float ZoomDamping = 6f;
938	
939	    private readonly MonoDreams.Component.Camera _camera;
940	    private readonly CameraDemoScreen _screen;
941	    private readonly EntitySet _activeBallTargets;
942	    private float _currentZoom = 1f;
943	
944	    public bool IsEnabled { get; set; } = true;
945	
946	    public CameraLagZoomSystem(World world, MonoDreams.Component.Camera camera, CameraDemoScreen screen)
947	    {
948	        _camera = camera;
949	        _screen = screen;
950	        // The ball only carries CameraFollowTargetComponent while in follow mode, so
951	        // this set is non-empty exactly when the dot is the camera target.
952	        _activeBallTargets = world.GetEntities()
953	            .With<PlayerBallTag>()
954	            .With<CameraFollowTargetComponent>()
955	            .With<TransformComponent>()
956	            .AsSet();
957	    }
958	
959	    public void Update(GameState state)
960	    {
961	        if (!IsEnabled) return;
962	
963	        var targetZoom = 1f;
964	        if (_screen.CornerZoomDistance is { } cornerDistance)
965	        {
966	            // Corner priority owns the zoom while engaged: the camera looks at the fixed
967	            // corner point, so scale by that point's distance from the corner center.
968	            var t = MathHelper.Clamp(cornerDistance / CornerZoomReferenceDistance, 0f, 1f);
969	            targetZoom = 1f - t * MaxZoomOut;
970	        }
971	        else
972	        {
973	            // Otherwise scale by the active red-dot's follow lag.
974	            foreach (var entity in _activeBallTargets.GetEntities())
975	            {
976	                if (!entity.Get<CameraFollowTargetComponent>().IsActive) continue;
977	                var lag = (entity.Get<TransformComponent>().Position - _camera.Position).Length();
978	                var t = MathHelper.Clamp(lag / MaxLag, 0f, 1f);
979	                targetZoom = 1f - t * MaxZoomOut;
980	                break;
981	            }
982	        }
983	
984	        var smooth = 1f - (float)Math.Exp(-ZoomDamping * state.Time);
985	        _currentZoom = MathHelper.Lerp(_currentZoom, targetZoom, smooth);
986	        _camera.Zoom = _currentZoom;
987	    }
988	
989	    public void Dispose()
990	    {
991	        _activeBallTargets.Dispose();
992	        GC.SuppressFinalize(this);
993	    }
994	}
