/// True while the camera follows the red dot AND the dot's center sits inside the
/// center zone (5). <see cref="CameraShakeSystem"/> reads this and fires a short,
/// decaying "hit" shake on the rising edge (the dot entering the zone). Fixed modes
/// never report true — the camera isn't tracking the dot then, so a shake would be
/// meaningless.
public bool IsBallInCenterZone
{
    get
    {
        if (_mode != Mode.Follow || !_ball.IsAlive) return false;
        var center = _ball.Get<TransformComponent>().Position;
        var topLeft = ZoneTopLeft(Mode.FixedCenter);
        var zone = new Rectangle((int)topLeft.X, (int)topLeft.Y, (int)ZoneSize, (int)ZoneSize);
        return zone.Contains((int)center.X, (int)center.Y);
    }
}

