/// Layers a short, rapid screen shake on top of the resolved follow position to sell a
/// "the player just took a hit" moment. While the camera follows the red dot and the dot
/// enters the center zone (5) — see <see cref="CameraDemoScreen.IsBallInCenterZone"/> — the
/// system fires a burst of trauma on the rising edge; the trauma decays to zero over a
/// fraction of a second and drives a small, high-frequency positional jitter that fades
/// with it. Holding the dot in the zone does not re-trigger — it is one hit per entry, so
/// starting centered (the dot's default spot) produces no shake until it leaves and returns.
///
/// It runs last in the update pipeline and writes <c>Camera.Position</c> after
/// <see cref="CameraFollowSystem"/> — the documented composable-shake pattern (the camera
/// overview's extension points: "write to the same Camera … last-write-wins per frame").
/// To keep the jitter from bleeding into the smoothed follow path (the follow system lerps
/// from <c>Camera.Position</c>), each frame it subtracts the offset it layered on last frame
/// to recover the clean followed base, then re-adds a fresh offset on top.
public class CameraShakeSystem : ISystem<GameState>
{
    // Peak positional offset in world units — kept small so the shake reads as a jolt,
    // not a camera throw.
    private const float MaxShakeOffset = 6f;
    // Trauma drains linearly to zero in 1 / TraumaDecayPerSecond seconds (~0.4s here),
    // so each hit is a brief burst rather than a sustained rumble.
    private const float TraumaDecayPerSecond = 2.5f;

    private readonly MonoDreams.Component.Camera _camera;
    private readonly CameraDemoScreen _screen;
    private readonly Random _rng = new();
    private Vector2 _appliedOffset = Vector2.Zero;
    private float _trauma;
    private bool _wasInZone;

    public bool IsEnabled { get; set; } = true;

    public CameraShakeSystem(MonoDreams.Component.Camera camera, CameraDemoScreen screen)
    {
        _camera = camera;
        _screen = screen;
    }

    public void Update(GameState state)
    {
        if (!IsEnabled) return;

        // Recover the clean follow position by peeling off the offset we layered on last
        // frame, so the shake stays additive and never accumulates into the path
        // CameraFollowSystem smooths from.
        var basePosition = _camera.Position - _appliedOffset;

        // Rising edge: the dot just entered the center zone in follow mode → take a hit.
        var inZone = _screen.IsBallInCenterZone;
        if (inZone && !_wasInZone) _trauma = 1f;
        _wasInZone = inZone;

        _trauma = MathHelper.Clamp(_trauma - TraumaDecayPerSecond * state.Time, 0f, 1f);

        // Magnitude falls off as trauma² for a sharp initial jolt that settles quickly;
        // a fresh random direction each frame makes it a rapid buzz rather than a wobble.
        var magnitude = MaxShakeOffset * _trauma * _trauma;
        var offset = magnitude <= 0f
            ? Vector2.Zero
            : new Vector2(
                (float)(_rng.NextDouble() * 2.0 - 1.0),
                (float)(_rng.NextDouble() * 2.0 - 1.0)) * magnitude;

        _camera.Position = basePosition + offset;
        _appliedOffset = offset;
    }

    public void Dispose() => GC.SuppressFinalize(this);
}

