/// True while the camera follows the red dot AND the dot's center sits inside the
/// center zone (5). <see cref="CameraShakeSystem"/> reads this and fires a short,
/// decaying "hit" shake on the rising edge (the dot entering the zone). Fixed modes
/// never report true — the camera isn't tracking the dot then, so a shake would be
/// meaningless.
public bool IsBallInCenterZone
{
    get
    {
        if (_mode != Mode.Follow || !_ball.IsAlive) return false;
        var center = _ball.Get<TransformComponent>().Position;
        var topLeft = ZoneTopLeft(Mode.FixedCenter);
        var zone = new Rectangle((int)topLeft.X, (int)topLeft.Y, (int)ZoneSize, (int)ZoneSize);
        return zone.Contains((int)center.X, (int)center.Y);
    }
}

input.new_string:
/// Which flanking hit square the red dot currently sits in, or <c>None</c>. Reports
/// <c>None</c> outside follow mode — the camera isn't tracking the dot then, so a jolt
/// centred on it would be meaningless. <see cref="CameraHitSystem"/> reads this and
/// fires on the rising edge (the dot entering a square).
public HitZone BallHitZone
{
    get
    {
        if (_mode != Mode.Follow || !_ball.IsAlive) return HitZone.None;
        var center = _ball.Get<TransformComponent>().Position;
        if (HitSquareRect(-HitSquareOffsetX).Contains((int)center.X, (int)center.Y)) return HitZone.Left;
        if (HitSquareRect(HitSquareOffsetX).Contains((int)center.X, (int)center.Y)) return HitZone.Right;
        return HitZone.None;
    }
}

/// World-space rectangle of a hit square centred at <paramref name="centerX"/> on the
/// horizontal axis (the squares straddle y = 0).
private static Rectangle HitSquareRect(float centerX)
{
    var half = (int)(HitSquareSize / 2f);
    return new Rectangle((int)centerX - half, -half, (int)HitSquareSize, (int)HitSquareSize);
}

/// Flashes the struck square yellow and (re)starts its blink timer. Called by
/// <see cref="CameraHitSystem"/> on the frame the dot enters the square.
public void BlinkHitSquare(HitZone zone)
{
    switch (zone)
    {
        case HitZone.Left:  _leftBlink = HitBlinkDuration;  SetHitSquareColor(_leftHitSquare, SproutPalette.SoftYellow); break;
        case HitZone.Right: _rightBlink = HitBlinkDuration; SetHitSquareColor(_rightHitSquare, SproutPalette.SoftYellow); break;
    }
}

/// Ticks down the yellow flashes; when one expires its square reverts to red. Driven
/// each frame by <see cref="CameraHitSystem"/>. Colors are only rewritten on the
/// expiry transition, not every frame.
public void UpdateHitSquareBlinks(float dt)
{
    if (_leftBlink > 0f && (_leftBlink -= dt) <= 0f)
    {
        _leftBlink = 0f;
        SetHitSquareColor(_leftHitSquare, SproutPalette.Crimson);
    }
    if (_rightBlink > 0f && (_rightBlink -= dt) <= 0f)
    {
        _rightBlink = 0f;
        SetHitSquareColor(_rightHitSquare, SproutPalette.Crimson);
    }
}

