    // Seeded true so the dot's default centered spawn isn't read as a fresh entry on the
    // first frame — a hit fires only on a real outside→inside transition.
    private bool _wasInZone = true;

    public bool IsEnabled { get; set; } = true;

    public CameraShakeSystem(MonoDreams.Component.Camera camera, CameraDemoScreen screen)
    {
        _camera = camera;
        _screen = screen;
    }

    public void Update(GameState state)
    {
        if (!IsEnabled) return;

        // Recover the clean follow position by peeling off the offset we layered on last
        // frame, so the shake stays additive and never accumulates into the path
        // CameraFollowSystem smooths from.
        var basePosition = _camera.Position - _appliedOffset;

        // Rising edge: the dot just entered the center zone in follow mode → take a hit.
        var inZone = _screen.IsBallInCenterZone;
        if (inZone && !_wasInZone) _trauma = 1f;
        _wasInZone = inZone;

        _trauma = MathHelper.Clamp(_trauma - TraumaDecayPerSecond * state.Time, 0f, 1f);

        // Magnitude falls off as trauma² for a sharp initial jolt that settles quickly;
        // a fresh random direction each frame makes it a rapid buzz rather than a wobble.
        var magnitude = MaxShakeOffset * _trauma * _trauma;
        var offset = magnitude <= 0f
            ? Vector2.Zero
            : new Vector2(
                (float)(_rng.NextDouble() * 2.0 - 1.0),
                (float)(_rng.NextDouble() * 2.0 - 1.0)) * magnitude;

        _camera.Position = basePosition + offset;
        _appliedOffset = offset;
    }

    public void Dispose() => GC.SuppressFinalize(this);
}

