        _lastZone = zone;

        _shakeTrauma = MathHelper.Clamp(_shakeTrauma - TraumaDecayPerSecond * state.Time, 0f, 1f);
        _rotateTrauma = MathHelper.Clamp(_rotateTrauma - TraumaDecayPerSecond * state.Time, 0f, 1f);
        _rotatePhase += state.Time;

