        var shakeMag = MaxShakeOffset * _shakeTrauma * _shakeTrauma;
        var offset = shakeMag <= 0f
            ? Vector2.Zero
            : new Vector2(
                (float)(_rng.NextDouble() * 2.0 - 1.0),
                (float)(_rng.NextDouble() * 2.0 - 1.0)) * shakeMag;

