        _appliedOffset = offset;
        _camera.Rotation = (_camera.Rotation - _appliedRotation) + angle;
        _appliedRotation = angle;

        _screen.UpdateHitSquareBlinks(state.Time);
    }

    public void Dispose() => GC.SuppressFinalize(this);
}

